def frame(rows: int = 3) -> pl.DataFrame:
    return pl.DataFrame({"player": [f"p{n}" for n in range(rows)], "wins": list(range(rows))})


@pytest.fixture
def session() -> Session:
    made = Session()
    made.namespace["q1"] = frame()
    made.sources["q1"] = "SmashDb console"
    made.namespace["big"] = frame(mentions.WHOLE_ROWS + 1)
    made.namespace["n"] = 5
    return made


def paths(text: str, session: Session) -> list[str]:
    return [mention.path for mention in mentions.find(text, session)]


# -- what counts as a mention ---------------------------------------------------------


def test_only_the_users_variables_are_mentions(session: Session) -> None:
    text = "compare @q1 with @big, mail me@q1.com, @nobody @pl @db @_hidden @@q1 and @q1 again"
    assert paths(text, session) == ["q1", "big"]


def test_a_dotted_path_names_a_column_and_stops_where_the_sentence_goes_on(session: Session) -> None:
    assert paths("@q1.player", session) == ["q1.player"]
    assert isinstance(mentions.find("@q1.player", session)[0].value, pl.Series)
    # "Thanks" is no part of q1: the mention is q1
    assert paths("look at @q1.Thanks", session) == ["q1"]
    assert paths("see @q1.", session) == ["q1"]


def test_a_path_never_calls_or_reaches_private_parts(session: Session) -> None:
    calls = []

    class Thing:
        _secret = 1
        plain = 2

        def method(self) -> int:
            calls.append(1)
            return 3

    session.namespace["thing"] = Thing()
    assert paths("@thing.plain @thing.method @thing._secret", session) == ["thing.plain", "thing"]
    assert not calls


def test_a_console_is_reached_by_its_parts(session: Session) -> None:
    session.namespace["r3"] = DbConsole(session.db, "select 1", frame())
    assert paths("@r3.df @r3.sql", session) == ["r3.df", "r3.sql"]


# -- one method call, at the end ----------------------------------------------------------


def test_an_allowed_method_is_called_with_plain_arguments(session: Session) -> None:
    head = mentions.find("the top of @big.head(2), please", session)[0]
    assert (head.path, head.error, head.value.height) == ("big.head(2)", "", 2)
    counts = mentions.find("@q1.wins.value_counts()", session)[0]
    assert (counts.path, counts.value.height) == ("q1.wins.value_counts()", 3)
    ordered = mentions.find('@q1.sort("wins", descending=True)', session)[0]
    assert ordered.value["wins"].to_list() == [2, 1, 0]
    # brackets and quotes inside the arguments don't end the call
    best = mentions.find('@q1.sql("select max(wins) as most from self") (see above)', session)[0]
    assert best.value.row(0) == (2,)
    assert mentions.problems("@big.head(2) and @q1.wins.value_counts()", session) == ""


def test_a_call_is_part_of_what_the_ai_gets(session: Session) -> None:
    block = mentions.context("@big.head(2)", session, tool=True)
    assert "@big.head(2) (made by: python): polars DataFrame, 2 rows" in block
    assert "p0,0" in block
    assert "p2," not in block


@pytest.mark.parametrize(
    ("text", "why"),
    [
        ('@q1.write_csv("/tmp/never.csv")', "write_csv() isn't allowed"),
        ('@q1.filter(pl.col("wins") > 1)', "filter() isn't allowed"),
        ('@q1.sort(pl.col("wins"))', "plain values"),
        ("@q1.head(__import__('os').getcwd())", "plain values"),
        ('@q1.head("five")', "failed: TypeError"),
        ("@q1.head(2", "brackets are not closed"),
        ("@q1.head(1).tail(1)", "only one method call"),
        ("@n.bit_length()", "isn't allowed"),
    ],
)
def test_a_call_that_isnt_allowed_or_fails_is_a_problem(session: Session, text: str, why: str) -> None:
    assert why in mentions.problems(f"look at {text}", session)
    assert why in mentions.find(text, session)[0].error
    assert not Path("/tmp/never.csv").exists()  # noqa: S108  # the refused call's target


def test_brackets_only_make_a_call_after_a_method_name(session: Session) -> None:
    # after a variable, or a column: the sentence going on
    assert paths("@q1 (the saved one)", session) == ["q1"]
    assert paths("@q1.wins(see above)", session) == ["q1.wins"]
    # a method without brackets is not a part: the mention is the variable
    assert paths("@q1.head", session) == ["q1"]
    assert mentions.problems("@q1 (x) @q1.wins(y) @q1.head", session) == ""


def test_a_message_of_only_a_call_is_bare(session: Session) -> None:
    found = mentions.bare('@q1.sql("select player from self where wins > 0") @n', session) or []
    assert [mention.path for mention in found] == ['q1.sql("select player from self where wins > 0")', "n"]
    assert mentions.bare("@q1.head(2) why?", session) is None


# -- the list after a dot (as the console's) ---------------------------------------------


def labels(session: Session, typed: str) -> list[str]:
    return [row["label"] for row in mentions.complete(session, typed)]


def test_after_a_dot_come_columns_then_attributes_and_allowed_methods(session: Session) -> None:
    found = mentions.complete(session, "q1.")
    assert [row["label"] for row in found[:2]] == ["player", "wins"]
    assert {row["kind"] for row in found} == {"column", "attribute", "method"}
    by_label = {row["label"]: row for row in found}
    assert by_label["head()"] == {"label": "head()", "kind": "method", "detail": "method", "insert": "q1.head("}
    assert by_label["shape"]["insert"] == "q1.shape"
    assert by_label["wins"]["detail"] == "Series"
    # only what a mention may call, and nothing private
    assert "write_csv()" not in by_label
    assert "filter()" not in by_label
    assert not [label for label in by_label if label.startswith("_")]
    assert {label.removesuffix("()") for label in by_label if label.endswith("()")} == set(mentions.CALLS[pl.DataFrame])


def test_the_list_filters_as_typed_and_works_at_any_depth(session: Session) -> None:
    assert labels(session, "q1.he")[:2] == ["head()", "height"]
    assert "value_counts()" in labels(session, "q1.wins.")
    assert "str" not in labels(session, "q1.wins.")  # polars' accessor objects hold nothing to show
    session.namespace["r3"] = DbConsole(session.db, "select 1", frame())
    assert labels(session, "r3.")[:2] == ["df", "sql"]
    assert labels(session, "r3.df.")[:2] == ["player", "wins"]


def test_nothing_is_listed_for_what_isnt_a_variable_or_has_no_dot(session: Session) -> None:
    assert mentions.complete(session, "q1") == []
    assert mentions.complete(session, "nobody.") == []
    assert mentions.complete(session, "q1.nope.") == []
    assert mentions.complete(None, "q1.") == []


def test_everything_listed_can_be_used(session: Session) -> None:
    """The list never offers what a mention would then ignore or refuse."""
    for row in mentions.complete(session, "q1."):
        if row["kind"] == "method":
            assert row["label"].removesuffix("()") in mentions.allowed_calls(session.namespace["q1"])
        else:
            assert paths(f"@{row['insert']}", session) == [row["insert"]]


